package com.motohub.next;
import android.app.*;import android.content.*;import android.text.InputType;import android.widget.*;import org.json.*;import java.util.*;
final class GroupUi {
 final MainActivity a;final GroupClient api=GroupClient.INSTANCE;GroupUi(MainActivity a){this.a=a;}
 void work(MainActivity.Work w){new SocialUi(a).run(()->{w.run();a.runOnUiThread(()->{if(!a.isDestroyed()&&!a.isFinishing()){a.close();open();}});});}
 void launch(){work(api::load);}
 void open(){LinearLayout p=a.page("그룹 라이딩");a.label(p,Sharing.status,17,a.fg,true);if(Sharing.enabled)a.action(p,"위치 공유 즉시 중지",true,()->{Sharing.stop();a.close();open();});a.action(p,"비공개 방 만들기",true,this::create);a.action(p,"방 목록 새로고침",false,()->work(api::load));if(api.groups.length()==0)a.label(p,"참가한 방이나 초대가 없어요.",17,a.muted,false);for(int i=0;i<api.groups.length();i++){JSONObject g=api.groups.optJSONObject(i);a.action(p,g.optString("name")+ (api.joined(g.optString("id"))?"":" · 초대 받음"),false,()->detail(g));}a.label(p,"승인된 방 구성원끼리만 위치를 공유합니다. 위치는 5초 주기로 동기화하며, 공유는 매번 직접 켜야 합니다.",15,a.muted,false);a.show();}
 void create(){SocialUi f=new SocialUi(a);LinearLayout p=a.page("비공개 라이딩 방");EditText name=f.input(p,"방 이름","",InputType.TYPE_CLASS_TEXT);a.chips(p,new String[]{"주말 와인딩","번개 라이딩","투어","야간 라이딩"},new String[]{"주말 와인딩","번개 라이딩","투어","야간 라이딩"},name);EditText meet=f.input(p,"집결지","",InputType.TYPE_CLASS_TEXT),dest=f.input(p,"목적지","",InputType.TYPE_CLASS_TEXT);a.action(p,"방 만들기",true,()->{String n=name.getText().toString(),m=meet.getText().toString(),d=dest.getText().toString();a.close();work(()->api.create(n,m,d));});a.show();}
 void detail(JSONObject g){String id=g.optString("id");LinearLayout p=a.page(g.optString("name"));a.label(p,"집결지 · "+g.optString("meetup","미정"),17,a.fg,false);a.label(p,"목적지 · "+g.optString("destination","미정"),17,a.fg,false);
  if(!api.joined(id)){a.action(p,"초대 수락하고 참가",true,()->work(()->api.action("accept",id,"")));a.action(p,"초대 거절",false,()->work(()->api.action("leave",id,"")));a.show();return;}
  a.action(p,"그룹 위치 지도",true,()->a.startActivity(new Intent(a,GroupMapActivity.class).putExtra("dark",a.dark).putExtra("group",id).putExtra("title",g.optString("name"))));a.label(p,Sharing.status,16,a.muted,false);
  if(Sharing.enabled)a.action(p,"위치 공유 즉시 중지",true,()->{Sharing.stop();a.close();detail(g);});else a.action(p,"이 그룹에 내 위치 공유",false,()->new AlertDialog.Builder(a).setTitle("위치를 공유할까요?").setMessage("GPS 기록 중인 내 위치와 상태를 이 방의 승인된 구성원에게 전송합니다. 화면을 꺼도 지속 알림과 함께 공유합니다. 중지하거나 GPS 기록을 종료하면 전송을 중단합니다.").setNegativeButton("취소",null).setPositiveButton("동의하고 공유",(d,w)->work(()->{if(!a.getSystemService(NotificationManager.class).areNotificationsEnabled())throw new java.io.IOException("알림을 허용한 뒤 공유하세요.");Sharing.start(id);})).show());
  if(Sharing.enabled&&Sharing.group.equals(id))a.action(p,"주행 상태 변경",false,()->a.choose("현재 상태",new String[]{"주행","정차","주유","휴식"},v->{Sharing.state(v.equals("주행")?"moving":v.equals("정차")?"stopped":v.equals("주유")?"fuel":v.equals("휴식")?"rest":"moving");a.toast("다음 위치 전송에 반영합니다.");}));
  if(g.optString("owner").equals(api.api.uid))a.action(p,"친구 초대",false,()->invite(id));
  a.divider(p);for(int i=0;i<api.members.length();i++){JSONObject m=api.members.optJSONObject(i);if(id.equals(m.optString("group_id")))a.label(p,api.api.name(m.optString("user_id"))+" · "+(m.optString("status").equals("accepted")?"참가":"초대 중"),16,a.fg,false);}
  a.action(p,g.optString("owner").equals(api.api.uid)?"방 종료":"방 나가기",false,()->new AlertDialog.Builder(a).setTitle("방을 종료하거나 나갈까요?").setNegativeButton("취소",null).setPositiveButton("확인",(d,w)->{if(Sharing.group.equals(id))Sharing.stop();work(()->api.action(g.optString("owner").equals(api.api.uid)?"close":"leave",id,""));}).show());a.show();
 }
 void invite(String group){List<String> ids=new ArrayList<>(),names=new ArrayList<>();SocialClient s=api.api;for(int i=0;i<s.requests.length();i++){JSONObject r=s.requests.optJSONObject(i);if(!r.optString("status").equals("accepted"))continue;String id=r.optString("sender").equals(s.uid)?r.optString("recipient"):r.optString("sender");ids.add(id);names.add(s.name(id));}if(ids.isEmpty()){a.toast("먼저 친구 요청을 수락해 주세요.");return;}new AlertDialog.Builder(a).setTitle("초대할 친구").setItems(names.toArray(new String[0]),(d,n)->work(()->api.action("invite",group,ids.get(n)))).show();}
}
